// A light face sitting on a darker base. Pressing sinks the face into the
// base; a tap plays down + up and then switches to `next`. Returns the face
// (a centred flex row) for the caller to fill.
lv_obj_t* Ui::arcadeButton(lv_obj_t* parent, int32_t w, lv_color_t faceColor,
                           lv_color_t baseColor, Mode next) {
  lv_obj_t* btn = lv_obj_create(parent);
  lv_obj_remove_style_all(btn);
  lv_obj_set_size(btn, w, kStartH);
  lv_obj_remove_flag(btn, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_set_ext_click_area(btn, 6);
  // Base and face have the same size; the base sits kStartDepth lower, so
  // the pushed-in face covers it exactly.
  auto layer = [&](lv_color_t color, int32_t y) {
    lv_obj_t* o = plain(btn, LV_FLEX_FLOW_ROW);
    lv_obj_add_flag(o, LV_OBJ_FLAG_IGNORE_LAYOUT);
    lv_obj_set_pos(o, 0, y);
    lv_obj_set_size(o, w, kStartH - kStartDepth);
    lv_obj_set_style_radius(o, 8, 0);
    lv_obj_set_style_bg_color(o, color, 0);
    lv_obj_set_style_bg_opa(o, LV_OPA_COVER, 0);
    lv_obj_set_style_border_color(o, kStartOutline, 0);
    lv_obj_set_style_border_width(o, 3, 0);
    return o;
  };
  layer(baseColor, kStartDepth);
  lv_obj_t* face = layer(faceColor, 0);
  lv_obj_set_flex_align(face, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER,
                        LV_FLEX_ALIGN_CENTER);
  lv_obj_t* shine = plain(face, LV_FLEX_FLOW_ROW);  // highlight along the top
  lv_obj_add_flag(shine, LV_OBJ_FLAG_IGNORE_LAYOUT);
  lv_obj_set_pos(shine, 6, 2);
  lv_obj_set_size(shine, w - 20, 3);
  lv_obj_set_style_bg_color(shine, lv_color_white(), 0);
  lv_obj_set_style_bg_opa(shine, LV_OPA_COVER, 0);
  lv_obj_set_user_data(btn, face);
  lv_obj_set_user_data(face, reinterpret_cast<void*>(static_cast<uintptr_t>(next)));
  lv_obj_add_event_cb(btn, onStartButton, LV_EVENT_PRESSED, this);
  lv_obj_add_event_cb(btn, onStartButton, LV_EVENT_PRESS_LOST, this);
  lv_obj_add_event_cb(btn, onStartButton, LV_EVENT_CLICKED, this);
  return face;
}

// Moves the START face to `y` (0 = up, kStartDepth = pushed in). With
// `wake`, the screensaver switches to startNext_ once the animation has finished.
void Ui::animateStart(lv_obj_t* face, int32_t y, uint32_t ms, bool wake) {
  lv_anim_t a;
  lv_anim_init(&a);
  lv_anim_set_var(&a, face);
  lv_anim_set_user_data(&a, this);
  lv_anim_set_values(&a, lv_obj_get_y(face), y);
  lv_anim_set_duration(&a, ms);
  lv_anim_set_path_cb(&a, y ? lv_anim_path_ease_in : lv_anim_path_overshoot);
  lv_anim_set_exec_cb(&a, [](void* obj, int32_t v) {
    lv_obj_set_y(static_cast<lv_obj_t*>(obj), v);
  });
  if (wake) {
    // Runs from lv_timer_handler(), not an event callback; update() rebuilds.
    lv_anim_set_completed_cb(&a, [](lv_anim_t* anim) {
      auto* self = static_cast<Ui*>(lv_anim_get_user_data(anim));
      if (self->mode_ == Mode::Screensaver) self->mode_ = self->startNext_;
    });
  }
  lv_anim_start(&a);  // replaces a running animation of the same face
}

void Ui::onStartButton(lv_event_t* e) {
  auto* self = static_cast<Ui*>(lv_event_get_user_data(e));
  auto* btn = static_cast<lv_obj_t*>(lv_event_get_current_target(e));
  auto* face = static_cast<lv_obj_t*>(lv_obj_get_user_data(btn));
  switch (lv_event_get_code(e)) {
    case LV_EVENT_PRESSED:
      self->animateStart(face, kStartDepth, kStartDownMs, false);
      break;
    case LV_EVENT_CLICKED:
      // A quick tap may release before the face is down: finish the press,
      // then spring back and wake.
      if (lv_obj_get_y(face) < kStartDepth) {
        lv_anim_delete(face, nullptr);
        lv_obj_set_y(face, kStartDepth);
      }
      self->startNext_ =
          static_cast<Mode>(reinterpret_cast<uintptr_t>(lv_obj_get_user_data(face)));
      self->animateStart(face, 0, kStartUpMs, true);
      break;
    case LV_EVENT_PRESS_LOST:  // slid off: pop back up, stay asleep
      self->animateStart(face, 0, kStartUpMs, false);
      break;
    default:
      break;
  }
}

uint32_t Ui::nextRand() {
  // Step the state and stir in the clock, then mix all bits (MurmurHash3
  // fmix32) so even a 1 ms clock difference changes the whole result.
  // Plain "LCG + clock" isn't enough: the clock only touches the low bits,
  // so the first pick after boot was almost always the same message.
  rng_ += 0x9E3779B9u + clock_();
  uint32_t h = rng_;
  h ^= h >> 16;
  h *= 0x85EBCA6Bu;
  h ^= h >> 13;
  h *= 0xC2B2AE35u;
  h ^= h >> 16;
  return h >> 16;
}

const char* Ui::nextGrindMessage() {
  size_t pick = nextRand() % kGrindMessageCount;
  if (pick == grindMessage_) pick = (pick + 1) % kGrindMessageCount;
  grindMessage_ = pick;
  return kGrindMessages[pick];
}

void Ui::startConfetti() {
  const float w = lv_obj_get_width(root_);
  const float h = lv_obj_get_height(root_);
  for (auto& c : confetti_) {
    c.obj = lv_obj_create(root_);
    lv_obj_remove_style_all(c.obj);
    lv_obj_set_size(c.obj, 4 + nextRand() % 3, 7 + nextRand() % 4);
    lv_obj_set_style_radius(c.obj, 1, 0);
    lv_obj_set_style_bg_color(c.obj, lv_color_hex(kConfettiColors[nextRand() % kConfettiColorCount]),
                              0);
    lv_obj_set_style_bg_opa(c.obj, LV_OPA_COVER, 0);
    lv_obj_add_flag(c.obj, LV_OBJ_FLAG_FLOATING);
    lv_obj_remove_flag(c.obj, LV_OBJ_FLAG_CLICKABLE);
    // Start spread above the screen so they rain in rather than appear at once.
    c.x = nextRand() % static_cast<uint32_t>(w);
    c.y = -static_cast<float>(nextRand() % static_cast<uint32_t>(h));
    c.vx = static_cast<float>(nextRand() % 41) - 20.0f;
    c.vy = 70.0f + nextRand() % 80;
  }
  confettiOn_ = true;
  confettiStartMs_ = confettiLastMs_ = clock_();
  moveConfetti();
}

void Ui::moveConfetti() {
  const uint32_t now = clock_();
  float dt = (now - confettiLastMs_) / 1000.0f;
  confettiLastMs_ = now;
  if (dt > 0.2f) dt = 0.2f;
  const bool respawn = now - confettiStartMs_ < kConfettiSpawnMs;
  const float w = lv_obj_get_width(root_);
  const float h = lv_obj_get_height(root_);
  const int32_t padL = lv_obj_get_style_pad_left(root_, 0);
  const int32_t padT = lv_obj_get_style_pad_top(root_, 0);

  bool anyVisible = false;
  for (auto& c : confetti_) {
    if (lv_obj_has_flag(c.obj, LV_OBJ_FLAG_HIDDEN)) continue;
    c.x += c.vx * dt;
    c.y += c.vy * dt;
    if (c.y > h) {
      if (!respawn) {
        lv_obj_add_flag(c.obj, LV_OBJ_FLAG_HIDDEN);
        continue;
      }
      c.y = -10;
      c.x = nextRand() % static_cast<uint32_t>(w);
    }
    anyVisible = true;
    lv_obj_set_pos(c.obj, static_cast<int32_t>(c.x) - padL,
                   static_cast<int32_t>(c.y) - padT);
  }
  confettiOn_ = anyVisible;
}

